<div class="page-heading"><div><h1><?= $deleting?'Move voter to Deleted voters':'Review deleted voter' ?></h1><p><?= e($person['full_name']) ?> · Voter ID <?= e($person['voter_id']) ?> · Record #<?= e($person['id']) ?></p></div><a class="btn btn-light" href="<?= e(url($deleting?'voter':'deleted_voters',$deleting?['id'=>$person['id']]:[])) ?>">Cancel</a></div>
<section class="card"><div class="card-body">
<?php if($deleting): ?><p>This removes the voter from active lists and statistics. Their record and photo are retained. An administrator can restore or permanently delete them later.</p>
<form method="post" action="<?= e(url('voters')) ?>"><?= csrf() ?><input type="hidden" name="_action" value="voter_trash"><input type="hidden" name="id" value="<?= e($person['id']) ?>"><input type="hidden" name="review_token" value="<?= e($token) ?>"><button class="btn btn-danger" name="mode" value="delete">Move to Deleted voters</button></form>
<?php else: ?>
<?php if($duplicates): ?><div class="alert alert-warning">Possible duplicates found. Matching names can belong to different people. Compare the records before choosing an action.</div><div class="table-responsive"><table class="table"><thead><tr><th>Existing active record</th><th>Voter ID</th><th>Type</th></tr></thead><tbody><?php foreach($duplicates as $duplicate): ?><tr><td><a href="<?= e(url($duplicate['membership_id']?'member':'voter',['id'=>$duplicate['membership_id']?:$duplicate['id']])) ?>" target="_blank" rel="noopener"><?= e($duplicate['full_name']) ?> (#<?= e($duplicate['id']) ?>)</a></td><td><?= e($duplicate['voter_id']) ?></td><td><?= $duplicate['membership_id']?'Member — protected':'Voter' ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<form method="post" action="<?= e(url('deleted_voters')) ?>"><?= csrf() ?><input type="hidden" name="_action" value="voter_trash"><input type="hidden" name="id" value="<?= e($person['id']) ?>"><input type="hidden" name="review_token" value="<?= e($token) ?>">
<?php if($duplicates): ?><label class="form-check mb-3"><input class="form-check-input" type="checkbox" name="different_people" value="1"><span class="form-check-label">These are different people. Restore as a separate voter.</span></label><?php endif; ?><button class="btn btn-primary" name="mode" value="restore">Restore voter</button>
<?php $targets=[];foreach($duplicates as $duplicate){if(!$duplicate['membership_id']){$targets[$duplicate['id']]=$duplicate['full_name'].' / '.$duplicate['voter_id'].' / #'.$duplicate['id'];}}if($targets): ?>
<hr><h2 class="h5">Resolve a duplicate</h2><?= select_field('target_id','Existing voter',[''=>'Choose the existing record']+$targets,'') ?><p class="text-secondary">Merge keeps the existing voter and fills only missing details and photo from this deleted record. Existing values win; conflicting details and the deleted duplicate are removed. Memberships are protected. Alternatively, replace moves the selected existing voter to Deleted voters, then restores this record.</p><div class="d-flex gap-2 flex-wrap"><button class="btn btn-warning" name="mode" value="merge">Confirm merge into existing voter</button><button class="btn btn-outline-danger" name="mode" value="replace">Move existing voter to deleted list and restore this one</button></div><?php endif; ?>
</form>
<hr><details><summary class="text-danger">Permanently delete this record</summary><p class="mt-3">This permanently removes the deleted voter and their photo. It cannot be restored. Type the voter ID <strong><?= e($person['voter_id']) ?></strong> to confirm.</p><form method="post" action="<?= e(url('deleted_voters')) ?>"><?= csrf() ?><input type="hidden" name="_action" value="voter_trash"><input type="hidden" name="id" value="<?= e($person['id']) ?>"><input type="hidden" name="review_token" value="<?= e($token) ?>"><?= input('confirm_id','Confirm voter ID','','text',true,'maxlength="64" autocomplete="off"') ?><button class="btn btn-danger" name="mode" value="purge">Permanently delete voter</button></form></details>
<?php endif; ?></div></section>
